#[ORM\Entity]
class Product
{
    #[ORM\Id]
    #[ORM\Column(type: 'integer')]
    private int $id;

    #[ORM\Version]
    #[ORM\Column(type: 'integer')]
    private int $version = 1;
}

function has_conflict(array $base, array $theirs, array $ours): bool
{
    $keys = array_unique(array_merge(
        array_keys($base),
        array_keys($theirs),
        array_keys($ours),
    ));

    foreach ($keys as $k) {
        $b = $base[$k] ?? null;
        $t = $theirs[$k] ?? null;
        $o = $ours[$k] ?? null;

        if ($t !== $b && $o !== $b && $t !== $o) {
            return true;
        }
    }

    return false;
}

